"""Execute a parsed :class:`minisql.ast.Query` against CSV tables.

The executor is the only part of minisql that touches the filesystem.  It
loads the table named by ``query.table`` from ``<directory>/<table>.csv``,
evaluates expressions (including aggregates and grouping), and returns a
:class:`minisql.result.Result`.
"""

from __future__ import annotations

import csv
import functools
import os
from dataclasses import dataclass

from . import values
from .ast import (
    Agg,
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    Query,
    Unary,
)
from .errors import QueryError
from .result import Result


# ---------------------------------------------------------------------------
# Tables
# ---------------------------------------------------------------------------


class _Table:
    """A loaded CSV file.

    ``columns`` keeps the header spelling in file order.  ``positions`` maps
    lowercased names to their index, so column lookup is case-insensitive and
    a duplicate header name is resolved to its last occurrence.  Rows are
    tuples in file order (already converted to values and padded to the
    header width).
    """

    __slots__ = ("columns", "positions", "rows")

    def __init__(self, columns, positions, rows):
        self.columns = columns
        self.positions = positions
        self.rows = rows

    def index(self, name):
        try:
            return self.positions[name.lower()]
        except KeyError:
            raise QueryError('unknown column "%s"' % name) from None


def _load_table(name, directory):
    path = os.path.join(os.fspath(directory), name + ".csv")
    try:
        with open(path, "r", newline="", encoding="utf-8") as handle:
            records = list(csv.reader(handle))
    except OSError as exc:
        detail = exc.strerror or str(exc)
        raise QueryError(
            'cannot read table "%s" from %s: %s' % (name, path, detail)
        ) from None
    except (csv.Error, UnicodeDecodeError) as exc:
        raise QueryError(
            'cannot read table "%s" from %s: %s' % (name, path, exc)
        ) from None

    if not records:
        raise QueryError('table "%s" is empty (missing header row)' % name)

    header = records[0]
    positions = {}
    for index, column in enumerate(header):
        positions[column.lower()] = index

    width = len(header)
    rows = []
    for record in records[1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        rows.append(tuple(values.coerce_cell(field) for field in record[:width]))

    return _Table(header, positions, rows)


# ---------------------------------------------------------------------------
# Small expression helpers
# ---------------------------------------------------------------------------


def _children(expr):
    """Return the direct sub-expressions of *expr*."""
    if isinstance(expr, Unary):
        return (expr.operand,)
    if isinstance(expr, Binary):
        return (expr.left, expr.right)
    if isinstance(expr, IsNull):
        return (expr.operand,)
    if isinstance(expr, InList):
        return (expr.operand,) + tuple(expr.items)
    if isinstance(expr, Between):
        return (expr.operand, expr.low, expr.high)
    if isinstance(expr, Like):
        return (expr.operand, expr.pattern)
    if isinstance(expr, (Func, Agg)):
        return tuple(expr.args)
    return ()


def _contains_agg(expr):
    if isinstance(expr, Agg):
        return True
    return any(_contains_agg(child) for child in _children(expr))


def _expr_key(expr):
    """A hashable, case-normalised form of *expr*.

    Column names are lowercased so that ``GROUP BY NAME`` matches
    ``SELECT name``, and literals carry a type tag so that ``TRUE`` does not
    compare equal to ``1``.
    """
    if isinstance(expr, Literal):
        return ("literal", type(expr.value).__name__, expr.value)
    if isinstance(expr, Column):
        return ("column", expr.name.lower())
    if isinstance(expr, Unary):
        return ("unary", expr.op, _expr_key(expr.operand))
    if isinstance(expr, Binary):
        return ("binary", expr.op, _expr_key(expr.left), _expr_key(expr.right))
    if isinstance(expr, IsNull):
        return ("isnull", _expr_key(expr.operand), expr.negated)
    if isinstance(expr, InList):
        return (
            "in",
            _expr_key(expr.operand),
            tuple(_expr_key(item) for item in expr.items),
            expr.negated,
        )
    if isinstance(expr, Between):
        return (
            "between",
            _expr_key(expr.operand),
            _expr_key(expr.low),
            _expr_key(expr.high),
            expr.negated,
        )
    if isinstance(expr, Like):
        return (
            "like",
            _expr_key(expr.operand),
            _expr_key(expr.pattern),
            expr.negated,
        )
    if isinstance(expr, Func):
        return ("func", expr.name.lower(), tuple(_expr_key(a) for a in expr.args))
    if isinstance(expr, Agg):
        return (
            "agg",
            expr.name.lower(),
            expr.star,
            tuple(_expr_key(a) for a in expr.args),
        )
    raise QueryError("unsupported expression: %r" % (expr,))


def _check_columns(expr, table):
    """Raise for any column in *expr* that the table does not have."""
    if isinstance(expr, Column):
        table.index(expr.name)
        return
    for child in _children(expr):
        _check_columns(child, table)


def _negate3(value):
    """Three-valued NOT."""
    if value is None:
        return None
    return not value


def _and3(left, right):
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _or3(left, right):
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


# ---------------------------------------------------------------------------
# Row / group evaluation context
# ---------------------------------------------------------------------------


class _Context:
    """Everything an expression needs: the table, a row and aggregate values.

    ``aggs`` is ``None`` outside a grouped context (which makes any aggregate
    expression an error).  In a grouped context it maps :func:`_expr_key` of
    each aggregate node to its value for the current group.
    """

    __slots__ = ("table", "row", "aggs")

    def __init__(self, table, row=None, aggs=None):
        self.table = table
        self.row = row
        self.aggs = aggs


def _eval(expr, ctx):
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Column):
        if ctx.row is None:
            raise QueryError('column "%s" is not available here' % expr.name)
        return ctx.row[ctx.table.index(expr.name)]

    if isinstance(expr, Unary):
        operand = _eval(expr.operand, ctx)
        op = expr.op.upper()
        if op == "-":
            if operand is None:
                return None
            if isinstance(operand, bool) or not isinstance(operand, (int, float)):
                raise QueryError("cannot negate a non-number")
            return -operand
        if op == "NOT":
            return _negate3(values.truth(operand))
        raise QueryError("unsupported unary operator %s" % expr.op)

    if isinstance(expr, Binary):
        op = expr.op
        upper = op.upper()
        if upper == "AND":
            return _and3(
                values.truth(_eval(expr.left, ctx)),
                values.truth(_eval(expr.right, ctx)),
            )
        if upper == "OR":
            return _or3(
                values.truth(_eval(expr.left, ctx)),
                values.truth(_eval(expr.right, ctx)),
            )
        left = _eval(expr.left, ctx)
        right = _eval(expr.right, ctx)
        if op in ("+", "-", "*", "/"):
            return values.arith(op, left, right)
        if op == "||":
            return values.concat(left, right)
        if op in ("=", "!=", "<", "<=", ">", ">="):
            return values.compare(op, left, right)
        raise QueryError("unsupported binary operator %s" % expr.op)

    if isinstance(expr, IsNull):
        result = _eval(expr.operand, ctx) is None
        return not result if expr.negated else result

    if isinstance(expr, InList):
        operand = _eval(expr.operand, ctx)
        items = [_eval(item, ctx) for item in expr.items]
        if operand is None:
            result = None
        else:
            result = False
            saw_null = False
            for item in items:
                if item is None:
                    saw_null = True
                elif values.compare("=", operand, item) is True:
                    result = True
                    break
            else:
                if saw_null:
                    result = None
        return _negate3(result) if expr.negated else result

    if isinstance(expr, Between):
        operand = _eval(expr.operand, ctx)
        low = _eval(expr.low, ctx)
        high = _eval(expr.high, ctx)
        result = _and3(
            values.compare("<=", low, operand),
            values.compare("<=", operand, high),
        )
        return _negate3(result) if expr.negated else result

    if isinstance(expr, Like):
        operand = _eval(expr.operand, ctx)
        pattern = _eval(expr.pattern, ctx)
        result = values.like(operand, pattern)
        return _negate3(result) if expr.negated else result

    if isinstance(expr, Func):
        args = [_eval(arg, ctx) for arg in expr.args]
        return values.call(expr.name.lower(), args)

    if isinstance(expr, Agg):
        if ctx.aggs is None:
            raise QueryError(
                "aggregate function %s is not allowed here" % expr.name.upper()
            )
        key = _expr_key(expr)
        if key not in ctx.aggs:
            raise QueryError(
                "aggregate function %s is not allowed here" % expr.name.upper()
            )
        return ctx.aggs[key]

    raise QueryError("unsupported expression: %r" % (expr,))


# ---------------------------------------------------------------------------
# SELECT list and ORDER BY plans
# ---------------------------------------------------------------------------


def _select_plan(query, table):
    """Return ``(output_names, exprs)``.

    ``exprs`` is ``None`` for ``SELECT *``; otherwise it holds one expression
    per output column.  A plain column gets the CSV header's spelling as its
    output name.
    """
    if query.columns is None:
        return list(table.columns), None

    names = []
    exprs = []
    for item in query.columns:
        exprs.append(item.expr)
        if item.alias is not None:
            names.append(item.alias)
        elif isinstance(item.expr, Column):
            names.append(table.columns[table.index(item.expr.name)])
        else:
            names.append(item.text)
    return names, exprs


@dataclass(frozen=True)
class _SortSpec:
    """One resolved ORDER BY item.

    ``kind`` is ``"output"`` (sort by ``output[index]``) or ``"expr"`` (sort by
    evaluating ``expr``).
    """

    kind: str
    index: int = -1
    expr: Expr = None
    descending: bool = False


def _resolve_order(query, output_names):
    lowered = [name.lower() for name in output_names]
    specs = []
    for item in query.order_by:
        expr = item.expr
        # An output column name takes priority (this is what makes aliases
        # shadow table columns in ORDER BY).
        if isinstance(expr, Column):
            name = expr.name.lower()
            if name in lowered:
                specs.append(
                    _SortSpec("output", lowered.index(name), None, item.descending)
                )
                continue
        if (
            isinstance(expr, Literal)
            and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)
        ):
            ordinal = expr.value
            if ordinal < 1 or ordinal > len(output_names):
                raise QueryError(
                    "ORDER BY position %d is out of range" % ordinal
                )
            specs.append(
                _SortSpec("output", ordinal - 1, None, item.descending)
            )
            continue
        specs.append(_SortSpec("expr", -1, expr, item.descending))
    return specs


def _sort_values(specs, output, ctx):
    return [
        output[spec.index] if spec.kind == "output" else _eval(spec.expr, ctx)
        for spec in specs
    ]


# ---------------------------------------------------------------------------
# DISTINCT, sorting and limits
# ---------------------------------------------------------------------------


def _value_key(value):
    """Hashable key implementing DISTINCT's type-aware equality.

    ``None`` equals ``None``; all numbers (including ``int``/``float``) compare
    numerically; booleans and strings only equal their own kind.  Mixed kinds
    are deliberately unequal rather than an error.
    """
    if value is None:
        return (0,)
    if isinstance(value, bool):
        return (1, value)
    if isinstance(value, (int, float)):
        return (2, value)
    if isinstance(value, str):
        return (3, value)
    return (4, type(value).__name__, repr(value))


def _row_key(row):
    return tuple(_value_key(value) for value in row)


def _compare_records(left, right, specs):
    for index, spec in enumerate(specs):
        a = left[index]
        b = right[index]
        if a is None or b is None:
            if a is None and b is None:
                continue
            # NULLs first ascending, last descending.
            if a is None:
                return 1 if spec.descending else -1
            return -1 if spec.descending else 1
        comparison = values.compare_values(a, b)
        if comparison:
            return -comparison if spec.descending else comparison
    return 0


def _finish(records, specs, query):
    """Apply DISTINCT, ORDER BY, LIMIT and OFFSET to projected records.

    A record is ``(output_tuple, sort_key_values)``.  The order is
    project -> distinct -> sort -> limit, as specified.
    """
    if query.distinct:
        seen = set()
        unique = []
        for record in records:
            key = _row_key(record[0])
            if key not in seen:
                seen.add(key)
                unique.append(record)
        records = unique

    if specs:
        def compare(left, right):
            return _compare_records(left[1], right[1], specs)

        records = sorted(
            records,
            key=functools.cmp_to_key(compare),
        )

    offset = query.offset if query.offset is not None else 0
    if query.limit is not None:
        records = records[offset:offset + query.limit]
    else:
        records = records[offset:]
    return [output for output, _keys in records]


# ---------------------------------------------------------------------------
# Execution
# ---------------------------------------------------------------------------


def _query_is_grouped(query, select_exprs):
    if query.group_by:
        return True
    if select_exprs is not None and any(
        _contains_agg(expr) for expr in select_exprs
    ):
        return True
    if query.having is not None and _contains_agg(query.having):
        return True
    return any(_contains_agg(item.expr) for item in query.order_by)


def _execute_ungrouped(query, table, output_names, select_exprs, specs):
    rows = table.rows
    if query.where is not None:
        rows = [
            row
            for row in rows
            if values.truth(_eval(query.where, _Context(table, row))) is True
        ]

    records = []
    for row in rows:
        ctx = _Context(table, row)
        # With no aggregate and no GROUP BY, HAVING is a per-row filter.
        if query.having is not None:
            if values.truth(_eval(query.having, ctx)) is not True:
                continue
        if select_exprs is None:
            output = tuple(row)
        else:
            output = tuple(_eval(expr, ctx) for expr in select_exprs)
        records.append((output, _sort_values(specs, output, ctx)))

    return Result(output_names, _finish(records, specs, query))


def _validate_aggregate(node):
    name = node.name.lower()
    if node.star:
        if name != "count":
            raise QueryError("only COUNT may be used with *")
        if node.args:
            raise QueryError("COUNT(*) takes no arguments")
    elif len(node.args) != 1:
        raise QueryError(
            "aggregate function %s takes exactly one argument"
            % node.name.upper()
        )


def _collect_aggregates(expr, collected):
    if isinstance(expr, Agg):
        if any(_contains_agg(arg) for arg in expr.args):
            raise QueryError("aggregate functions cannot be nested")
        _validate_aggregate(expr)
        collected.append(expr)
        return
    for child in _children(expr):
        _collect_aggregates(child, collected)


def _group_key_equal(left, right):
    for a, b in zip(left, right):
        if a is None or b is None:
            if a is None and b is None:
                continue
            return False
        if values.compare_values(a, b) != 0:
            return False
    return True


def _aggregate_value(node, rows, table):
    if node.star:
        return values.aggregate(
            node.name.lower(), [None] * len(rows), star=True
        )
    argument = node.args[0]
    arguments = [
        _eval(argument, _Context(table, row)) for row in rows
    ]
    return values.aggregate(node.name.lower(), arguments, star=False)


def _check_group_refs(expr, group_keys):
    """Enforce "columns outside aggregates must be GROUP BY expressions".

    A whole expression equal to a GROUP BY expression is accepted.  Descending
    through e.g. ``LOWER(category)`` is allowed when ``category`` itself is
    grouped, but a bare column that is not in ``GROUP BY`` is an error.
    """
    if _expr_key(expr) in group_keys:
        return
    if isinstance(expr, Agg):
        # Columns inside an aggregate are always allowed.
        return
    if isinstance(expr, Column):
        raise QueryError(
            'column "%s" must appear in GROUP BY or be used in an aggregate'
            % expr.name
        )
    for child in _children(expr):
        _check_group_refs(child, group_keys)


def _execute_grouped(query, table, output_names, select_exprs, specs):
    checked = (
        select_exprs
        if select_exprs is not None
        else [Column(name) for name in table.columns]
    )

    collected = []
    for expr in checked:
        _collect_aggregates(expr, collected)
    if query.having is not None:
        _collect_aggregates(query.having, collected)
    for spec in specs:
        if spec.kind == "expr":
            _collect_aggregates(spec.expr, collected)

    aggregate_nodes = {}
    for node in collected:
        aggregate_nodes.setdefault(_expr_key(node), node)

    group_keys = {_expr_key(expr) for expr in query.group_by}
    for expr in checked:
        _check_group_refs(expr, group_keys)
    if query.having is not None:
        _check_group_refs(query.having, group_keys)
    for spec in specs:
        if spec.kind == "expr":
            _check_group_refs(spec.expr, group_keys)

    if query.where is not None:
        filtered = [
            row
            for row in table.rows
            if values.truth(_eval(query.where, _Context(table, row))) is True
        ]
    else:
        filtered = list(table.rows)

    if query.group_by:
        groups = []
        group_values = []
        for row in filtered:
            ctx = _Context(table, row)
            key = tuple(_eval(expr, ctx) for expr in query.group_by)
            for index, existing in enumerate(group_values):
                if _group_key_equal(key, existing):
                    groups[index].append(row)
                    break
            else:
                group_values.append(key)
                groups.append([row])
    else:
        # No GROUP BY: exactly one group, even when there are no rows.
        groups = [filtered]

    records = []
    for group in groups:
        aggregate_values = {
            key: _aggregate_value(node, group, table)
            for key, node in aggregate_nodes.items()
        }
        representative = group[0] if group else None
        ctx = _Context(table, representative, aggregate_values)

        if query.having is not None:
            if values.truth(_eval(query.having, ctx)) is not True:
                continue

        if select_exprs is None:
            if representative is None:
                raise QueryError(
                    "SELECT * cannot be evaluated for an empty group"
                )
            output = tuple(representative)
        else:
            output = tuple(_eval(expr, ctx) for expr in select_exprs)

        records.append((output, _sort_values(specs, output, ctx)))

    return Result(output_names, _finish(records, specs, query))


def execute(query, directory="."):
    """Execute *query* against the CSV files in *directory*."""
    table = _load_table(query.table, directory)

    output_names, select_exprs = _select_plan(query, table)
    specs = _resolve_order(query, output_names)
    grouped = _query_is_grouped(query, select_exprs)

    if query.where is not None and _contains_agg(query.where):
        raise QueryError("aggregate functions are not allowed in WHERE")
    if any(_contains_agg(expr) for expr in query.group_by):
        raise QueryError("aggregate functions are not allowed in GROUP BY")

    # Validate every table-column reference up front, even when there are no
    # rows to evaluate.  ORDER BY references to output columns are not table
    # columns, so they are skipped here.
    if query.where is not None:
        _check_columns(query.where, table)
    for expr in query.group_by:
        _check_columns(expr, table)
    checked = (
        select_exprs
        if select_exprs is not None
        else [Column(name) for name in table.columns]
    )
    for expr in checked:
        _check_columns(expr, table)
    if query.having is not None:
        _check_columns(query.having, table)
    for spec in specs:
        if spec.kind == "expr":
            _check_columns(spec.expr, table)

    if grouped:
        return _execute_grouped(
            query, table, output_names, select_exprs, specs
        )
    return _execute_ungrouped(
        query, table, output_names, select_exprs, specs
    )

